-- Sessions that produced at least one error, with the first error per session.
WITH errors AS (
    SELECT session_id,
           MIN(occurred_at)                      AS first_error_at,
           COUNT(*)                              AS error_count
    FROM   events
    WHERE  severity IN ('ERROR', 'FATAL')
      AND  occurred_at >= NOW() - INTERVAL '7 days'
    GROUP BY session_id
)
SELECT s.session_id,
       s.started_at,
       e.first_error_at,
       e.error_count,
       EXTRACT(EPOCH FROM (e.first_error_at - s.started_at)) AS seconds_to_first_error
FROM   sessions s
JOIN   errors   e USING (session_id)
WHERE  s.started_at >= NOW() - INTERVAL '7 days'
ORDER BY seconds_to_first_error ASC
LIMIT  200;

