	if attempts < 1 {
		return errors.New("attempts must be at least 1")
	}
	var last error
	for i := 0; i < attempts; i++ {
		if err := fn(); err == nil {
			return nil
		} else {
			last = err
		}
		if i == attempts-1 {
			break
		}
		// Exponential backoff with full jitter; the context wins if it expires first.
		delay := base * time.Duration(1<<uint(i))
		jittered := time.Duration(rand.Int63n(int64(delay) + 1))
		select {
		case <-time.After(jittered):
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	return fmt.Errorf("after %d attempts: %w", attempts, last)
}

